<?php
declare(strict_types=1);
require dirname(__DIR__) . '/config/bootstrap.php';$user=require_role('admin');$pdo=db();
$stats=['Guru'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='guru' AND is_active=1")->fetchColumn(),'Orang Tua'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='orang_tua' AND is_active=1")->fetchColumn(),'Siswa Aktif'=>(int)$pdo->query("SELECT COUNT(*) FROM students WHERE status='aktif'")->fetchColumn(),'Kelas Aktif'=>(int)$pdo->query("SELECT COUNT(*) FROM classes WHERE aktif=1")->fetchColumn()];
$todayReports=(int)$pdo->query('SELECT COUNT(*) FROM daily_student_reports WHERE tanggal=CURDATE()')->fetchColumn();$activeStudents=max(1,(int)$pdo->query("SELECT COUNT(*) FROM students WHERE status='aktif'")->fetchColumn());$completeness=min(100,round($todayReports/$activeStudents*100));
$pending=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE approval_status='pending'")->fetchColumn();$unlinked=(int)$pdo->query("SELECT COUNT(*) FROM users u LEFT JOIN parent_student_links l ON l.parent_id=u.id AND l.status='active' WHERE u.role='orang_tua' AND l.parent_id IS NULL")->fetchColumn();$noTeacher=(int)$pdo->query("SELECT COUNT(*) FROM classes WHERE aktif=1 AND teacher_id IS NULL")->fetchColumn();
$recent=$pdo->query('SELECT e.*,a.username actor,t.username target FROM account_security_events e LEFT JOIN users a ON a.id=e.actor_user_id LEFT JOIN users t ON t.id=e.target_user_id ORDER BY e.created_at DESC LIMIT 8')->fetchAll();
$pageTitle='Dashboard Monitoring';require ROOT_PATH.'/includes/header.php';
?>
