<section class="grid grid-4"><?php $i=0;foreach($stats as $label=>$value):?><article class="stat <?= $i++===0?'green':'' ?>"><small><?= e($label) ?></small><strong><?= $value ?></strong><span class="muted">Data aktif</span></article><?php endforeach;?></section>
<section class="grid grid-2" style="margin-top:20px"><article class="card"><h2 class="card-title"><span class="icon-box">✓</span>Kelengkapan Hari Ini</h2><div style="display:flex;justify-content:space-between;align-items:end"><div><strong style="font-size:44px"><?= $todayReports ?>/<?= $activeStudents===1&&$stats['Siswa Aktif']===0?0:$activeStudents ?></strong><p class="muted">Laporan harian siswa</p></div><strong style="font-size:28px;color:var(--green-2)"><?= $completeness ?>%</strong></div><div class="progress"><span style="width:<?= $completeness ?>%"></span></div><a class="btn btn-soft" style="margin-top:18px" href="<?= url('admin/completeness.php') ?>">Lihat Kelengkapan</a></article><article class="card"><h2 class="card-title"><span class="icon-box">!</span>Peringatan Sistem</h2><div class="compact-list"><div class="compact-item"><span>Akun menunggu persetujuan</span><span class="badge <?= $pending?'badge-yellow':'badge-green' ?>"><?= $pending ?></span></div><div class="compact-item"><span>Orang Tua belum terhubung</span><span class="badge <?= $unlinked?'badge-yellow':'badge-green' ?>"><?= $unlinked ?></span></div><div class="compact-item"><span>Kelas tanpa wali mengaji</span><span class="badge <?= $noTeacher?'badge-yellow':'badge-green' ?>"><?= $noTeacher ?></span></div></div></article></section>
<section class="card" style="margin-top:20px"><div class="filter-row"><h2 class="card-title" style="margin:0"><span class="icon-box">◴</span>Aktivitas Terbaru</h2><a class="btn btn-soft btn-sm" href="<?= url('admin/audit.php') ?>">Buka Audit Lengkap</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Aktivitas</th><th>Pelaku</th><th>Target</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $row):?><tr><td><?= e(format_date_id($row['created_at'],true)) ?></td><td class="name"><?= e(str_replace('_',' ',ucwords($row['event_type'],'_'))) ?></td><td><?= e($row['actor']??'Sistem/Tamu') ?></td><td><?= e($row['target']??'-') ?></td><td><span class="badge <?= $row['status']==='success'?'badge-green':($row['status']==='blocked'?'badge-yellow':'badge-red') ?>"><?= e($row['status']) ?></span></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="5"><div class="empty"><strong>Belum ada aktivitas</strong>Audit akan muncul setelah sistem digunakan.</div></td></tr><?php endif;?></tbody></table></div></section>
